command:
python3 -c '
import urllib.request
import urllib.parse
import json
import os

group_name = "${answer1}"
okta_url = os.environ.get("OKTA_URL")
token = os.environ.get(
    "OKTA_API_TOKEN"
)

if not okta_url or not token:
    print(json.dumps({"error": "OKTA_URL and OKTA_API_TOKEN must be set"}))
    exit(1)

encoded_name = urllib.parse.quote(group_name)
search_url = (
    f"{okta_url}/api/v1/groups?q={encoded_name}"
)
req = urllib.request.Request(
    search_url,
    headers={
        "Authorization": f"SSWS {token}",
        "Accept": "application/json",
        "Content-Type": "application/json",
    },
)

try:
    with urllib.request.urlopen(req) as response:
        groups = json.loads(response.read().decode())
        matching_group = next(
            (g for g in groups if g.get("profile", {}).get("name") == group_name),
            None,
        )

        if not matching_group and groups:
            matching_group = groups[0]

        if not matching_group:
            print(
                json.dumps({
                    "status": "error",
                    "message": f"Group not found: {group_name}",
                })
            )
            exit(1)

        group_id = matching_group["id"]
        delete_url = f"{okta_url}/api/v1/groups/{group_id}"
        del_req = urllib.request.Request(
            delete_url,
            method="DELETE",
            headers={
                "Authorization": f"SSWS {token}",
                "Accept": "application/json",
            },
        )

        with urllib.request.urlopen(del_req) as del_resp:
            if del_resp.status == 204 or del_resp.status == 200:
                print(
                    json.dumps({
                        "status": "success",
                        "message": f"Group '{group_name}' ({group_id}) deleted successfully.",
                        "groupId": group_id,
                    })
                )
            else:
                print(
                    json.dumps({
                        "status": "error",
                        "message": f"Failed to delete group, status code: {del_resp.status}",
                    })
                )
except Exception as e:
    print(json.dumps({"status": "error", "message": str(e)}))
'
